from decimal import Decimal, InvalidOperation

_AMOUNT_RE = re.compile(r'[0-9]+(?:\.[0-9]{1,2})?')


class InsufficientFunds(Exception):
    pass


class Ledger:
    _PENNY = Decimal('0.01')
    _FEE = Decimal('1.50')

    def __init__(self, overdraft_limit='0.00'):
        self._overdraft_limit = self._parse_overdraft_limit(overdraft_limit)
        self._balance = Decimal('0.00')
        self._history = []

    @staticmethod
    def _format_amount(value):
        value = value.quantize(Ledger._PENNY)
        if value == 0:
            value = Decimal('0.00')
        return f'{value:.2f}'

    @staticmethod
    def _parse_money(value, allow_zero):
        if not isinstance(value, str):
            raise TypeError('amount must be a string')
        if not _AMOUNT_RE.fullmatch(value):
            raise ValueError('invalid amount format')
        try:
            d = Decimal(value)
        except InvalidOperation:
            raise ValueError('invalid amount format')
        if not allow_zero and d == 0:
            raise ValueError('amount must be greater than zero')
        return d

    def _parse_overdraft_limit(self, value):
        return self._parse_money(value, allow_zero=True)

    def _parse_transaction(self, value):
        return self._parse_money(value, allow_zero=False)

    def deposit(self, amount):
        d = self._parse_transaction(amount)
        self._balance += d
        self._history.append(('deposit', self._format_amount(d)))

    def withdraw(self, amount):
        d = self._parse_transaction(amount)
        new_balance = self._balance - d
        if new_balance < -self._overdraft_limit:
            raise InsufficientFunds('withdrawal would exceed overdraft limit')
        self._balance = new_balance
        self._history.append(('withdraw', self._format_amount(d)))
        if self._balance < 0:
            self._balance -= self._FEE
            self._history.append(('fee', self._format_amount(self._FEE)))

    def balance(self):
        return self._format_amount(self._balance)

    def history(self):
        return list(self._history)
