import heapq


def _validate_k(k):
    if type(k) is not int or k < 1:
        raise ValueError("k must be an int >= 1")


def _validate_meeting(start, end):
    if type(start) is not int or type(end) is not int:
        raise ValueError("start and end must be ints")
    if start >= end:
        raise ValueError("start must be less than end")


def _allocate(meetings, k):
    _validate_k(k)
    n = len(meetings)
    if n == 0:
        return []

    events = []
    for idx, mtg in enumerate(meetings):
        if not isinstance(mtg, (list, tuple)) or len(mtg) != 2:
            raise ValueError("each meeting must be a pair (start, end)")
        start, end = mtg
        _validate_meeting(start, end)
        events.append((start, end, end - start, idx))

    events.sort(key=lambda x: (x[0], x[3]))

    result = [None] * n
    available = list(range(k))
    heapq.heapify(available)
    busy = []

    for start, end, duration, idx in events:
        while busy and busy[0][0] <= start:
            release, room = heapq.heappop(busy)
            heapq.heappush(available, room)

        if available:
            room = heapq.heappop(available)
            actual_start = start
            actual_end = end
        else:
            t = busy[0][0]
            while busy and busy[0][0] == t:
                release, room = heapq.heappop(busy)
                heapq.heappush(available, room)
            room = heapq.heappop(available)
            actual_start = t
            actual_end = t + duration

        result[idx] = (room, actual_start, actual_end)
        heapq.heappush(busy, (actual_end, room))

    return result


def assign_rooms(meetings, k):
    return _allocate(meetings, k)


def busiest_room(meetings, k):
    _validate_k(k)
    if len(meetings) == 0:
        return 0

    assignments = _allocate(meetings, k)
    counts = [0] * k
    for room, _, _ in assignments:
        counts[room] += 1

    best = 0
    for room in range(1, k):
        if counts[room] > counts[best]:
            best = room
    return best
