import math
from collections import deque


def _validate_limit(limit):
    if isinstance(limit, bool) or not isinstance(limit, (int, float)):
        raise ValueError("limit must be an int or float")
    if not limit >= 0:
        raise ValueError("limit must be non-negative")


def _validate_value(x):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise TypeError("values must contain int or float elements")
    if isinstance(x, float) and math.isnan(x):
        raise ValueError("values must not contain NaN")


def _calm_ends(values, limit):
    _validate_limit(limit)
    n = len(values)
    max_d = deque()
    min_d = deque()
    left = 0
    for right in range(n):
        x = values[right]
        _validate_value(x)
        while max_d and values[max_d[-1]] <= x:
            max_d.pop()
        max_d.append(right)
        while min_d and values[min_d[-1]] >= x:
            min_d.pop()
        min_d.append(right)
        while True:
            cur_max = values[max_d[0]]
            cur_min = values[min_d[0]]
            if cur_max - cur_min <= limit:
                break
            left += 1
            if max_d[0] < left:
                max_d.popleft()
            if min_d[0] < left:
                min_d.popleft()
        yield left, right


def longest_calm(values, limit):
    best_i = 0
    best_j = 0
    best_len = 0
    for left, right in _calm_ends(values, limit):
        cur_len = right - left + 1
        if cur_len > best_len or (cur_len == best_len and left < best_i):
            best_len = cur_len
            best_i = left
            best_j = right + 1
    return (best_i, best_j)


def count_calm(values, limit):
    total = 0
    for left, right in _calm_ends(values, limit):
        total += right - left + 1
    return total
