import heapq


class CycleError(ValueError):
    def __init__(self, nodes):
        self.nodes = sorted(nodes)
        super().__init__(f'cycle detected: {self.nodes}')


def _graph(nodes, edges):
    node_set = set(nodes)
    adj = {n: [] for n in node_set}
    indeg = {n: 0 for n in node_set}
    seen = set()
    for before, after in edges:
        key = (before, after)
        if key in seen:
            continue
        seen.add(key)
        if before not in node_set or after not in node_set:
            raise ValueError(
                f'unknown node: {before if before not in node_set else after}'
            )
        adj[before].append(after)
        indeg[after] += 1
    return node_set, adj, indeg


def topo_order(nodes, edges):
    node_set, adj, indeg = _graph(nodes, edges)
    heap = [n for n, d in indeg.items() if d == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for m in adj[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                heapq.heappush(heap, m)
    if len(order) != len(node_set):
        raise CycleError(node_set - set(order))
    return order


def layers(nodes, edges):
    node_set, adj, indeg = _graph(nodes, edges)
    heap = [n for n, d in indeg.items() if d == 0]
    heapq.heapify(heap)
    result = []
    placed = set()
    while heap:
        layer = []
        count = len(heap)
        for _ in range(count):
            n = heapq.heappop(heap)
            layer.append(n)
            placed.add(n)
            for m in adj[n]:
                indeg[m] -= 1
                if indeg[m] == 0:
                    heapq.heappush(heap, m)
        result.append(layer)
    if len(placed) != len(node_set):
        raise CycleError(node_set - placed)
    return result
