import re

_ROMAN_RE = re.compile(
    r"^(?=[MDCLXVI])M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$"
)

_VALUES = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)

_SYMBOLS = {
    "I": 1, "V": 5, "X": 10, "L": 50,
    "C": 100, "D": 500, "M": 1000,
}


def to_roman(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an int")
    if n < 1 or n > 3999:
        raise ValueError("n must be in the range 1..3999")
    parts = []
    for value, numeral in _VALUES:
        while n >= value:
            parts.append(numeral)
            n -= value
    return "".join(parts)


def from_roman(s):
    if not isinstance(s, str):
        raise TypeError("s must be a str")
    if not _ROMAN_RE.fullmatch(s):
        raise ValueError("not a canonical Roman numeral")
    total = 0
    length = len(s)
    for i, ch in enumerate(s):
        v = _SYMBOLS[ch]
        if i + 1 < length and v < _SYMBOLS[s[i + 1]]:
            total -= v
        else:
            total += v
    if total < 1 or total > 3999 or to_roman(total) != s:
        raise ValueError("not a canonical Roman numeral")
    return total


def is_roman(s):
    try:
        from_roman(s)
    except (TypeError, ValueError):
        return False
    return True
