def merge(intervals):
    cleaned = []
    for interval in intervals:
        start, end = interval
        if start > end:
            raise ValueError("interval start must not be greater than end")
        if start == end:
            continue
        cleaned.append((start, end))
    cleaned.sort(key=lambda item: item[0])
    result = []
    for start, end in cleaned:
        if result and start <= result[-1][1]:
            last_start, last_end = result[-1]
            if end > last_end:
                result[-1] = (last_start, end)
        else:
            result.append((start, end))
    return result


def subtract(a, b):
    merged_a = merge(a)
    merged_b = merge(b)
    result = []
    j = 0
    n = len(merged_b)
    for start_a, end_a in merged_a:
        current_start = start_a
        while current_start < end_a and j < n:
            start_b, end_b = merged_b[j]
            if end_a <= start_b:
                break
            if current_start >= end_b:
                j += 1
                continue
            if current_start < start_b:
                result.append((current_start, start_b))
            current_start = end_b
            j += 1
        if current_start < end_a:
            result.append((current_start, end_a))
    return result


def total_length(intervals):
    return sum(end - start for start, end in merge(intervals))
