from fractions import Fraction

__all__ = ["evaluate"]


class _Token:
    __slots__ = ("type", "value")

    def __init__(self, type_, value=None):
        self.type = type_
        self.value = value


def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch == " " or ch == "\t":
            i += 1
            continue
        if "0" <= ch <= "9":
            j = i
            while j < n and "0" <= text[j] <= "9":
                j += 1
            tokens.append(_Token("INT", int(text[i:j])))
            i = j
            continue
        if ch in "+-*/^()":
            tokens.append(_Token(ch))
            i += 1
            continue
        raise ValueError(f"Invalid character: {ch!r}")
    tokens.append(_Token("EOF"))
    return tokens


def _pow_fraction(base, exp):
    if exp.denominator != 1:
        raise ValueError("Exponent must be a whole number")
    e = exp.numerator // exp.denominator

    if base == 0:
        if e < 0:
            raise ZeroDivisionError("0 cannot be raised to a negative power")
        if e == 0:
            return Fraction(1, 1)
        return Fraction(0, 1)

    if e < 0:
        base = Fraction(1, 1) / base
        e = -e

    result = Fraction(1, 1)
    while e:
        if e & 1:
            result *= base
        base *= base
        e >>= 1
    return result


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _current(self):
        return self.tokens[self.pos]

    def _advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        if self._current().type == "EOF":
            raise ValueError("Empty expression")
        value = self._expr()
        if self._current().type != "EOF":
            raise ValueError("Unexpected token after complete expression")
        return value

    def _expr(self):
        value = self._term()
        while self._current().type in ("+", "-"):
            op = self._advance().type
            rhs = self._term()
            if op == "+":
                value += rhs
            else:
                value -= rhs
        return value

    def _term(self):
        value = self._unary()
        while self._current().type in ("*", "/"):
            op = self._advance().type
            rhs = self._unary()
            if op == "*":
                value *= rhs
            else:
                value = Fraction(value, rhs)
        return value

    def _unary(self):
        if self._current().type == "-":
            self._advance()
            return -self._unary()
        if self._current().type == "+":
            raise ValueError("Unary plus is not allowed")
        return self._power()

    def _power(self):
        base = self._atom()
        if self._current().type == "^":
            self._advance()
            exp = self._unary()
            return _pow_fraction(base, exp)
        return base

    def _atom(self):
        tok = self._current()
        if tok.type == "INT":
            self._advance()
            return Fraction(tok.value, 1)
        if tok.type == "(":
            self._advance()
            value = self._expr()
            if self._current().type != ")":
                raise ValueError("Expected ')'")
            self._advance()
            return value
        raise ValueError("Expected number or '('")


def evaluate(expr):
    tokens = _tokenize(expr)
    result = _Parser(tokens).parse()
    if result.denominator == 1:
        return result.numerator
    return result
