"""Span calculations with None as a barrier."""

def _validate_prices(prices):
    if not isinstance(prices, list):
        raise TypeError("prices must be a list")
    for p in prices:
        if p is None:
            continue
        if isinstance(p, bool) or not isinstance(p, (int, float)):
            raise TypeError("prices elements must be int, float, or None")


def spans(prices):
    _validate_prices(prices)
    result = []
    stack = []
    last_none = -1

    for i, p in enumerate(prices):
        if p is None:
            result.append(0)
            stack.clear()
            last_none = i
            continue

        while stack and prices[stack[-1]] <= p:
            stack.pop()

        if stack:
            result.append(i - stack[-1])
        else:
            result.append(i - last_none)

        stack.append(i)

    return result


def next_greater(prices):
    _validate_prices(prices)
    n = len(prices)
    result = [-1] * n
    stack = []

    for i in range(n - 1, -1, -1):
        p = prices[i]
        if p is None:
            stack.clear()
            result[i] = -1
            continue

        while stack and prices[stack[-1]] <= p:
            stack.pop()

        result[i] = stack[-1] if stack else -1
        stack.append(i)

    return result


def widest_span(prices):
    span_list = spans(prices)
    best_index = -1
    best_span = 0

    for i, s in enumerate(span_list):
        if s >= best_span:
            best_index = i
            best_span = s

    if best_span == 0:
        return (-1, 0)
    return (best_index, best_span)
