def _invalid(msg):
    raise ValueError(f'invalid cron: {msg}')


def _is_digits(s):
    return bool(s) and all('0' <= c <= '9' for c in s)


def expand_field(field, lo, hi):
    if not isinstance(field, str):
        _invalid('field must be a string')
    if field == '':
        _invalid('empty field')

    values = set()

    for item in field.split(','):
        if item == '':
            _invalid('empty item')

        if item.count('/') > 1:
            _invalid('multiple steps in item')

        if '/' in item:
            base, step_str = item.split('/')
            if not _is_digits(step_str):
                _invalid('step must be a positive integer')
            step = int(step_str)
            if step == 0:
                _invalid('step must be >= 1')
        else:
            base = item
            step = 1

        if base == '':
            _invalid('empty item')

        if base == '*':
            start = lo
            end = hi
        elif '-' in base:
            parts = base.split('-')
            if len(parts) != 2:
                _invalid('malformed range')
            a_str, b_str = parts
            if not _is_digits(a_str) or not _is_digits(b_str):
                _invalid('range bounds must be integers')
            a = int(a_str)
            b = int(b_str)
            if a > b:
                _invalid('range start greater than end')
            if a < lo or b > hi:
                _invalid('value out of range')
            start = a
            end = b
        else:
            if not _is_digits(base):
                _invalid('value must be an integer')
            n = int(base)
            if n < lo or n > hi:
                _invalid('value out of range')
            if step == 1:
                values.add(n)
                continue
            start = n
            end = hi

        for v in range(start, end + 1, step):
            values.add(v)

    return sorted(values)


def _parse_expr(expr):
    if not isinstance(expr, str):
        _invalid('expression must be a string')
    parts = expr.strip().split()
    if len(parts) != 2:
        _invalid('expression must have exactly two fields')
    minute_field, hour_field = parts
    minutes = expand_field(minute_field, 0, 59)
    hours = expand_field(hour_field, 0, 23)
    return minutes, hours


def cron_matches(expr, hour, minute):
    minutes, hours = _parse_expr(expr)
    return hour in hours and minute in minutes


def next_match(expr, hour, minute):
    minutes, hours = _parse_expr(expr)
    current = hour * 60 + minute

    for h in hours:
        for m in minutes:
            t = h * 60 + m
            if t > current:
                return (h, m)

    return (hours[0], minutes[0])
