class Scheduler:
    def __init__(self):
        self._tasks = {}
        self._order_counter = 0

    def add(self, name, priority, after=()):
        if name in self._tasks:
            raise ValueError(f"Task {name!r} already added")
        dependencies = set(after)
        for dep in dependencies:
            if dep not in self._tasks:
                raise KeyError(dep)
        self._tasks[name] = {
            "priority": priority,
            "after": dependencies,
            "order": self._order_counter,
            "status": "pending",
        }
        self._order_counter += 1

    def next(self):
        chosen_name = None
        chosen_priority = None
        chosen_order = None
        for name, task in self._tasks.items():
            if task["status"] != "pending":
                continue
            if all(self._tasks[dep]["status"] == "completed" for dep in task["after"]):
                priority = task["priority"]
                order = task["order"]
                if (
                    chosen_name is None
                    or priority > chosen_priority
                    or (priority == chosen_priority and order < chosen_order)
                ):
                    chosen_name = name
                    chosen_priority = priority
                    chosen_order = order
        if chosen_name is None:
            return None
        self._tasks[chosen_name]["status"] = "running"
        return chosen_name

    def complete(self, name):
        if name not in self._tasks:
            raise KeyError(name)
        if self._tasks[name]["status"] != "running":
            raise ValueError(f"Task {name!r} is not currently running")
        self._tasks[name]["status"] = "completed"

    def remaining(self):
        return sum(1 for task in self._tasks.values() if task["status"] != "completed")
