    for start, end, weight in sorted_intervals:
        idx = bisect_right(ends, start)
        cand_total = dp[idx][0] + weight
        cand_neg_count = dp[idx][1] - 1
        prev_total, prev_neg_count = dp[-1]

        if cand_total > prev_total or (
            cand_total == prev_total and cand_neg_count > prev_neg_count
        ):
            dp.append((cand_total, cand_neg_count))
        else:
            dp.append((prev_total, prev_neg_count))

    total, neg_count = dp[-1]
    return (total, -neg_count)


def max_parallel(intervals):
    _validate_intervals(intervals)
    if not intervals:
        return 0

    events = []
    for start, end, _ in intervals:
        events.append((start, 1))
        events.append((end, -1))

    events.sort(key=lambda x: (x[0], x[1]))

    current = 0
    best = 0
    for _, delta in events:
        current += delta
        if current > best:
            best = current

    return best
