import heapq
from collections import defaultdict


class MedianTracker:
    __slots__ = (
        "_prefer_high",
        "_low",
        "_high",
        "_low_count",
        "_high_count",
        "_low_size",
        "_high_size",
    )

    def __init__(self, prefer_high=False):
        self._prefer_high = bool(prefer_high)
        self._low = []
        self._high = []
        self._low_count = defaultdict(int)
        self._high_count = defaultdict(int)
        self._low_size = 0
        self._high_size = 0

    def _check_type(self, x):
        if isinstance(x, bool) or not isinstance(x, int):
            raise TypeError("value must be an int")

    def _clean_low(self):
        while self._low:
            v = -self._low[0]
            if self._low_count.get(v, 0):
                break
            heapq.heappop(self._low)

    def _clean_high(self):
        while self._high:
            v = self._high[0]
            if self._high_count.get(v, 0):
                break
            heapq.heappop(self._high)

    def _move_low_to_high(self):
        self._clean_low()
        v = -heapq.heappop(self._low)
        self._low_count[v] -= 1
        if self._low_count[v] == 0:
            del self._low_count[v]
        self._high_count[v] += 1
        heapq.heappush(self._high, v)
        self._low_size -= 1
        self._high_size += 1

    def _move_high_to_low(self):
        self._clean_high()
        v = heapq.heappop(self._high)
        self._high_count[v] -= 1
        if self._high_count[v] == 0:
            del self._high_count[v]
        self._low_count[v] += 1
        heapq.heappush(self._low, -v)
        self._high_size -= 1
        self._low_size += 1

    def _rebalance(self):
        if self._prefer_high:
            while self._high_size > self._low_size + 1:
                self._move_high_to_low()
            while self._low_size > self._high_size:
                self._move_low_to_high()
        else:
            while self._low_size > self._high_size + 1:
                self._move_low_to_high()
            while self._high_size > self._low_size:
                self._move_high_to_low()

    def add(self, x):
        self._check_type(x)
        if self._low:
            self._clean_low()
        if self._low and x <= -self._low[0]:
            heapq.heappush(self._low, -x)
            self._low_count[x] += 1
            self._low_size += 1
        else:
            heapq.heappush(self._high, x)
            self._high_count[x] += 1
            self._high_size += 1
        self._rebalance()

    def remove(self, x):
        self._check_type(x)
        if self._low_count.get(x, 0) == 0 and self._high_count.get(x, 0) == 0:
            raise ValueError("not present")
        if self._low_count.get(x, 0):
            self._low_count[x] -= 1
            if self._low_count[x] == 0:
                del self._low_count[x]
            self._low_size -= 1
        else:
            self._high_count[x] -= 1
            if self._high_count[x] == 0:
                del self._high_count[x]
            self._high_size -= 1
        self._rebalance()

    def median(self):
        total = self._low_size + self._high_size
        if total == 0:
            raise LookupError("empty")
        self._rebalance()
        self._clean_low()
        self._clean_high()
        if self._prefer_high:
            return self._high[0]
        return -self._low[0]

    def __len__(self):
        return self._low_size + self._high_size
