import re
from functools import cmp_to_key

_VERSION_RE = re.compile(
    r'^[vV]?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)


def _parse_prerelease(text):
    parts = text.split('.')
    result = []
    for part in parts:
        if part.isdigit():
            if len(part) > 1 and part[0] == '0':
                raise ValueError(
                    f"invalid version: prerelease identifier has leading zero: {part!r}"
                )
            result.append(int(part))
        else:
            result.append(part)
    return tuple(result)


def _compare_prerelease(a, b):
    if not a and not b:
        return 0
    if not a:
        return 1
    if not b:
        return -1
    for x, y in zip(a, b):
        x_num = isinstance(x, int)
        y_num = isinstance(y, int)
        if x_num and y_num:
            if x < y:
                return -1
            if x > y:
                return 1
        elif x_num:
            return -1
        elif y_num:
            return 1
        else:
            if x < y:
                return -1
            if x > y:
                return 1
    if len(a) < len(b):
        return -1
    if len(a) > len(b):
        return 1
    return 0


def parse_version(text):
    if not isinstance(text, str):
        raise ValueError("invalid version: not a string")
    match = _VERSION_RE.fullmatch(text)
    if not match:
        raise ValueError(f"invalid version: {text!r}")
    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    prerelease = _parse_prerelease(match.group(4)) if match.group(4) is not None else ()
    build = match.group(5) if match.group(5) is not None else None
    return (major, minor, patch, prerelease, build)


def compare_versions(a, b):
    a_parsed = parse_version(a)
    b_parsed = parse_version(b)
    for i in range(3):
        av = a_parsed[i]
        bv = b_parsed[i]
        if av < bv:
            return -1
        if av > bv:
            return 1
    return _compare_prerelease(a_parsed[3], b_parsed[3])


def sort_versions(versions):
    return sorted(versions, key=cmp_to_key(compare_versions))
