def parse_ini(text: str) -> dict[str, dict[str, str]]:
    result: dict[str, dict[str, str]] = {}
    current_section = ''
    current_key = None

    for i, raw in enumerate(text.split('\n'), start=1):
        line = raw[:-1] if raw.endswith('\r') else raw

        if line.strip() == '':
            current_key = None
            continue

        first_non_ws = line.lstrip()
        if first_non_ws and first_non_ws[0] in ';#':
            continue

        if line[0] in ' \t':
            if current_key is None:
                raise ValueError(f'line {i}: continuation without key')
            section, key = current_key
            value = result[section][key]
            appended = line.strip()
            if value == '':
                result[section][key] = appended
            else:
                result[section][key] = value + ' ' + appended
            continue

        stripped = line.strip()
        if stripped.startswith('[') and stripped.endswith(']'):
            current_section = stripped[1:-1].strip().lower()
            current_key = None
            result.setdefault(current_section, {})
            continue

        if '=' not in line:
            raise ValueError(f'line {i}: missing "="')

        key_part, value_part = line.split('=', 1)
        key = key_part.strip().lower()
        if key == '':
            raise ValueError(f'line {i}: empty key')

        result.setdefault(current_section, {})
        if key in result[current_section]:
            raise ValueError(f'duplicate key {key!r} in section {current_section!r}')

        result[current_section][key] = value_part.strip()
        current_key = (current_section, key)

    for section in result:
        for key in result[section]:
            value = result[section][key]
            if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
                result[section][key] = value[1:-1]

    return result
