def _parse_version(version):
    s = version.strip()
    if not s:
        raise ValueError("empty version")
    parts = s.split(".")
    result = []
    for part in parts:
        if not part or not part.isdigit():
            raise ValueError(f"invalid version part: {part!r}")
        result.append(int(part))
    return tuple(result)


def _compare(a, b):
    length = max(len(a), len(b))
    for i in range(length):
        av = a[i] if i < len(a) else 0
        bv = b[i] if i < len(b) else 0
        if av < bv:
            return -1
        if av > bv:
            return 1
    return 0


def _operator_func(op, spec_version):
    sv = _parse_version(spec_version)
    if op == "==":
        return lambda v: _compare(v, sv) == 0
    if op == "!=":
        return lambda v: _compare(v, sv) != 0
    if op == ">=":
        return lambda v: _compare(v, sv) >= 0
    if op == "<=":
        return lambda v: _compare(v, sv) <= 0
    if op == ">":
        return lambda v: _compare(v, sv) > 0
    if op == "<":
        return lambda v: _compare(v, sv) < 0
    if op == "~=":
        if len(sv) < 2:
            raise ValueError("~= requires at least two version components")
        upper = list(sv[:-1])
        upper[-1] += 1
        upper = tuple(upper)
        return lambda v: _compare(v, sv) >= 0 and _compare(v, upper) < 0
    raise ValueError(f"unknown operator: {op}")


def _parse_spec(spec):
    text = spec.strip()
    if not text:
        return []
    clauses = []
    for raw_clause in text.split(","):
        clause = raw_clause.strip()
        if not clause:
            raise ValueError("empty clause in spec")
        if clause.startswith("==") or clause.startswith("!=") or clause.startswith(">=") or clause.startswith("<=") or clause.startswith("~="):
            op = clause[:2]
            rest = clause[2:].strip()
        elif clause.startswith(">") or clause.startswith("<"):
            op = clause[0]
            rest = clause[1:].strip()
        else:
            raise ValueError(f"missing operator in clause: {clause!r}")
        if not rest:
            raise ValueError(f"missing version in clause: {clause!r}")
        clauses.append(_operator_func(op, rest))
    return clauses


def satisfies(version, spec):
    v = _parse_version(version)
    for check in _parse_spec(spec):
        if not check(v):
            return False
    return True


def max_satisfying(versions, spec):
    parsed = []
    for original in versions:
        parsed.append((original, _parse_version(original)))
    checks = _parse_spec(spec)
    best_original = None
    best_tuple = None
    for original, v in parsed:
        if not all(check(v) for check in checks):
            continue
        if best_tuple is None or _compare(v, best_tuple) > 0:
            best_tuple = v
            best_original = original
    return best_original
