import copy


def _decode_pointer(pointer):
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ValueError("pointer must be empty or start with '/'")
    raw_tokens = pointer[1:].split("/")
    decoded = []
    for raw in raw_tokens:
        out = []
        i = 0
        length = len(raw)
        while i < length:
            ch = raw[i]
            if ch == "~":
                i += 1
                if i >= length:
                    raise ValueError("unescaped '~' at end of token")
                nxt = raw[i]
                if nxt == "0":
                    out.append("~")
                elif nxt == "1":
                    out.append("/")
                else:
                    raise ValueError("invalid escape sequence")
            else:
                out.append(ch)
            i += 1
        decoded.append("".join(out))
    return decoded


def _list_index(token, container, allow_end=False):
    if token == "-":
        raise KeyError(token)
    if token == "0":
        idx = 0
    else:
        if not token or token[0] == "0" or not token.isdigit():
            raise KeyError(token)
        idx = int(token)
    if allow_end:
        if idx < 0 or idx > len(container):
            raise KeyError(token)
    else:
        if idx < 0 or idx >= len(container):
            raise KeyError(token)
    return idx


def resolve(doc, pointer):
    tokens = _decode_pointer(pointer)
    current = doc
    for token in tokens:
        if isinstance(current, dict):
            current = current[token]
        elif isinstance(current, list):
            idx = _list_index(token, current)
            current = current[idx]
        else:
            raise KeyError(token)
    return current


def set_value(doc, pointer, value):
    if pointer == "":
        return value
    tokens = _decode_pointer(pointer)
    new_doc = copy.deepcopy(doc)
    parent = new_doc
    for token in tokens[:-1]:
        if isinstance(parent, dict):
            parent = parent[token]
        elif isinstance(parent, list):
            idx = _list_index(token, parent)
            parent = parent[idx]
        else:
            raise KeyError(token)
    key = tokens[-1]
    if isinstance(parent, dict):
        parent[key] = value
    elif isinstance(parent, list):
        if key == "-":
            parent.append(value)
        else:
            idx = _list_index(key, parent, allow_end=True)
            if idx == len(parent):
                parent.append(value)
            else:
                parent[idx] = value
    else:
        raise KeyError(key)
    return new_doc


def escape_token(token):
    return token.replace("~", "~0").replace("/", "~1")
