def wrap_text(text, width):
    if not isinstance(width, int) or width < 2:
        raise ValueError("width must be an int >= 2")

    words = text.split()
    if not words:
        return []

    lines = []
    current = ""

    for word in words:
        word_len = len(word)

        if word_len > width:
            if current:
                lines.append(current)
                current = ""

            while word_len > width:
                lines.append(word[: width - 1] + "-")
                word = word[width - 1 :]
                word_len = len(word)

            current = word
        else:
            if current:
                if len(current) + 1 + word_len <= width:
                    current = current + " " + word
                else:
                    lines.append(current)
                    current = word
            else:
                current = word

    if current:
        lines.append(current)

    return lines
