import heapq

def validate_stream(events):
    if not isinstance(events, (list, tuple)):
        events = list(events)
    seen = set()
    for event in events:
        event_id = event[1]
        if event_id in seen:
            raise ValueError(f"duplicate id: {event_id!r}")
        seen.add(event_id)
    previous_key = None
    for event in events:
        key = (event[0], event[1])
        if previous_key is not None and key <= previous_key:
            raise ValueError(f"unsorted: {key!r} follows {previous_key!r}")
        previous_key = key
    return None

def diff_events(old, new):
    old_events = old if isinstance(old, (list, tuple)) else list(old)
    new_events = new if isinstance(new, (list, tuple)) else list(new)
    validate_stream(old_events)
    validate_stream(new_events)
    old_map = {event[1]: event for event in old_events}
    new_map = {event[1]: event for event in new_events}
    added = []
    removed = []
    moved = []
    changed = []
    for event in new_events:
        event_id = event[1]
        if event_id not in old_map:
            added.append(event_id)
            continue
        old_event = old_map[event_id]
        if event[0] != old_event[0]:
            moved.append(event_id)
        if event[2] != old_event[2]:
            changed.append(event_id)
    for event in old_events:
        event_id = event[1]
        if event_id not in new_map:
            removed.append(event_id)
    return {"added": added, "removed": removed, "moved": moved, "changed": changed}

def merge_streams(a, b):
    a_events = a if isinstance(a, (list, tuple)) else list(a)
    b_events = b if isinstance(b, (list, tuple)) else list(b)
    validate_stream(a_events)
    validate_stream(b_events)
    b_ids = {event[1] for event in b_events}
    a_only = [event for event in a_events if event[1] not in b_ids]
    merged = list(heapq.merge(
        a_only,
        b_events,
        key=lambda event: (event[0], event[1]),
    ))
    return merged
